function Vending({d}:any){let rev=d.machines.reduce((a:number,x:any)=>a+x[4],0),profit=d.machines.reduce((a:number,x:any)=>a+x[5],0);return <><KP><K l="Total machines" v="8" s="6 active · 2 attention" good icon={Warehouse}/><K l="Weekly revenue" v={euro(rev)} s="4.5% vs prior week" good/><K l="Monthly revenue" v={euro(33120)} s="€34,000 forecast" good/><K l="Gross profit" v={euro(profit)} s={`${(profit/rev*100).toFixed(1)}% margin`} good/></KP><KP><K l="Stock value" v={euro(6840)} s="Across all machines"/><K l="Low-stock alerts" v="4" s="2 critical products" bad/><K l="Refills required" v="3" s="Due within 48 hours" bad/><K l="Open faults" v="3" s="1 machine offline" bad/></KP><div className="grid"><Card title="Revenue & profit trend"><Chart d={d}/></Card><Card title="Payment split"><div className="pay"><ResponsiveContainer width="55%" height={240}><PieChart><Pie data={[{n:'Card',v:86},{n:'Cash',v:14}]} dataKey="v" innerRadius={58} outerRadius={88}><Cell fill="#2563eb"/><Cell fill="#f59e0b"/></Pie></PieChart></ResponsiveContainer><div><b>86%</b><span>Card payments</span><small>€7,448 card · €1,212 cash</small></div></div></Card></div><Machines d={d}/></>}
function Machines({d}:any){const role=sessionStorage.getItem('aa-role')||'owner',showMoney=role==='owner'||readPermissions()[role]?.financials;const heads=showMoney?['Machine & location','Status','Stock','Revenue','Gross profit','Card split']:['Machine & location','Status','Stock'];const rows=[...d.machines].sort((a:any,b:any)=>showMoney?b[4]-a[4]:a[6]-b[6]).map((x:any)=>showMoney?[`${x[1]} · ${x[0]} · ${x[2]}`,x[3],`${x[6]}%`,euro(x[4]),euro(x[5]),`${x[7]}%`]:[`${x[1]} · ${x[0]} · ${x[2]}`,x[3],`${x[6]}%`]);return <Card title="Machine performance"><Table heads={heads} rows={rows}/></Card>}function Inventory({d}:any){return <><KP><K l="Stock on hand" v={euro(6840)} s="421 units in machines"/><K l="Warehouse stock" v={euro(3920)} s="1,284 units available"/><K l="Low-stock SKUs" v="4" s="2 below reorder point" bad/><K l="Weekly units sold" v="1,163" s="8.2% increase" good/></KP><Card title="Product inventory & performance"><Table heads={['Product','Category','Warehouse stock','Par level','Weekly sales','Margin']} rows={d.products.map((x:any)=>[x[0],x[1],`${x[2]} units`,x[3],x[4],`${x[5]}%`])}/></Card></>}
function Operations({d}:any){return <div className="grid"><Card title="Refill schedule"><div className="alerts">{d.machines.filter((x:any)=>x[6]<55).map((x:any)=><div className="warn"><RefreshCw/><span><b>{x[1]} · {x[0]}</b><small>{x[6]}% stock · refill due within 48 hours</small></span></div>)}</div></Card><Card title="Open faults"><Table heads={['Machine','Issue','Priority','Open']} rows={d.faults}/></Card><Card title="Weekly expenses & site fees"><div className="rows"><Row a="Stock purchases" b={euro(2480)}/><Row a="Site commissions" b={euro(865)}/><Row a="Fuel & refill runs" b={euro(310)}/><Row a="Maintenance" b={euro(420)}/><Row a="Total expenses" b={euro(4075)} strong/></div></Card></div>}
function RoutePlanner({d}:any){const urgent=d.machines.filter((m:any)=>m[6]<55||m[3]!=='Active').sort((a:any,b:any)=>(a[3]==='Offline'?-30:0)+a[6]-((b[3]==='Offline'?-30:0)+b[6]));const[depot,setDepot]=useState('A and A Holdings Depot, Dublin');const[selected,setSelected]=useState<string[]>(()=>urgent.map((m:any)=>m[0]));const stops=urgent.filter((m:any)=>selected.includes(m[0]));const toggle=(id:string)=>setSelected(x=>x.includes(id)?x.filter(i=>i!==id):[...x,id]);const places=stops.map((m:any)=>`${m[1]}, ${m[2]}, Ireland`);const previewUrl=places.length?`https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(depot)}&destination=${encodeURIComponent(places.at(-1)!)}&waypoints=${places.slice(0,-1).map(encodeURIComponent).join('%7C')}&travelmode=driving`:'';const navigateUrl=places.length?`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(places[0])}&travelmode=driving&dir_action=navigate`:'';const km=Math.round(22+stops.length*13.5),mins=Math.round(km*1.3+stops.length*18);return <><RoutalConnection stops={stops}/><div className="routeHero"><div><em>SMART REFILL RUN</em><h2>Plan today’s machine route</h2><p>Stops are prioritised by faults and stock urgency. Start navigation uses your phone’s live location.</p></div><Route size={42}/></div><div className="routeStats"><K l="Selected stops" v={`${stops.length}`} s={`${urgent.length} recommended today`} icon={MapPin}/><K l="Estimated distance" v={`${km} km`} s="Planning estimate" icon={Navigation}/><K l="Estimated duration" v={`${Math.floor(mins/60)}h ${mins%60}m`} s="Includes 18 min per refill" icon={Clock}/><K l="Critical stops" v={`${stops.filter((m:any)=>m[6]<35||m[3]==='Offline').length}`} s="Visit first" bad icon={AlertTriangle}/></div><div className="routeGrid"><Card title="Route settings"><label className="depot"><span>Planning depot</span><input value={depot} onChange={e=>setDepot(e.target.value)} placeholder="Enter depot address"/></label><div className="routeList">{urgent.map((m:any)=><label className={selected.includes(m[0])?'selected':''}><input type="checkbox" checked={selected.includes(m[0])} onChange={()=>toggle(m[0])}/><b>{selected.includes(m[0])?stops.findIndex((s:any)=>s[0]===m[0])+1:'—'}</b><span><strong>{m[1]}</strong><small>{m[0]} · {m[2]}</small></span><i className={m[6]<35||m[3]==='Offline'?'critical':''}>{m[3]!=='Active'?m[3]:`${m[6]}% stock`}</i></label>)}</div><div className="routeActions"><a className={`mapsButton ${!stops.length?'disabled':''}`} href={navigateUrl||undefined} target="_blank" rel="noreferrer"><Navigation size={17}/>Start live navigation<ExternalLink size={15}/></a><a className={`previewButton ${!stops.length?'disabled':''}`} href={previewUrl||undefined} target="_blank" rel="noreferrer"><Route size={16}/>Preview full route</a></div><small className="mobileHint">On your phone, allow location access and open the link in the Google Maps app. Complete the first stop, then start the next one from this list.</small></Card><Card title="Recommended stop order"><div className="stops">{stops.length?stops.map((m:any,i:number)=><div><b>{i+1}</b><span><strong>{m[1]}</strong><small>{m[2]} · {m[6]}% stock</small></span><a href={`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(`${m[1]}, ${m[2]}, Ireland`)}&travelmode=driving&dir_action=navigate`} target="_blank" rel="noreferrer">Navigate</a></div>):<p>Select at least one machine to build a route.</p>}</div><div className="routeNote"><CheckCircle2 size={18}/><span><b>Live navigation</b><small>Google Maps uses the phone’s current position and live traffic for each selected stop.</small></span></div></Card></div></>}
function RoutalPlanner({d}:any){const recommended=d.machines.filter((m:any)=>m[6]<55||m[3]!=='Active').sort((a:any,b:any)=>(a[3]==='Offline'?-30:0)+a[6]-((b[3]==='Offline'?-30:0)+b[6]));const[selected,setSelected]=useState<string[]>(()=>recommended.map((m:any)=>m[0]));const stops=recommended.filter((m:any)=>selected.includes(m[0]));const toggle=(id:string)=>setSelected(x=>x.includes(id)?x.filter(i=>i!==id):[...x,id]);const exportStops=()=>{if(!stops.length)return;const esc=(v:any)=>`"${String(v).replaceAll('"','""')}"`;const rows=[['External ID','Name','Address','City','Country','Priority','Service time (min)','Notes'],...stops.map((m:any)=>[m[0],m[1],`${m[1]}, ${m[2]}`,m[2],'Ireland',m[6]<35||m[3]!=='Active'?'High':'Normal',18,`${m[6]}% stock; ${m[3]!=='Active'?m[3]:'Refill required'}`])];const blob=new Blob([rows.map(r=>r.map(esc).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`ai-vending-routal-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href)};return <><RoutalConnection stops={stops}/><div className="routeHero"><div><em>ROUTAL REFILL PLANNING</em><h2>Send today’s refill run to Routal</h2><p>Select the machines, download the stop file, then upload it to your existing Routal plan for optimization and driver dispatch.</p></div><Route size={42}/></div><div className="routeStats"><K l="Selected stops" v={`${stops.length}`} s={`${recommended.length} recommended today`} icon={MapPin}/><K l="Critical stops" v={`${stops.filter((m:any)=>m[6]<35||m[3]==='Offline').length}`} s="High priority in export" bad icon={AlertTriangle}/><K l="Service allowance" v={`${stops.length*18} min`} s="18 minutes per refill" icon={Clock}/><K l="Routing system" v="Routal" s="Planner + driver app" good icon={Navigation}/></div><div className="routeGrid"><Card title="Stops to send"><div className="routeList">{recommended.map((m:any)=><label className={selected.includes(m[0])?'selected':''}><input type="checkbox" checked={selected.includes(m[0])} onChange={()=>toggle(m[0])}/><b>{selected.includes(m[0])?stops.findIndex((s:any)=>s[0]===m[0])+1:'—'}</b><span><strong>{m[1]}</strong><small>{m[0]} · {m[2]}</small></span><i className={m[6]<35||m[3]==='Offline'?'critical':''}>{m[3]!=='Active'?m[3]:`${m[6]}% stock`}</i></label>)}</div><div className="routeActions"><button className="mapsButton" disabled={!stops.length} onClick={exportStops}><Save size={17}/>Download Routal stop file</button><a className="previewButton" href="https://planner.routal.com" target="_blank" rel="noreferrer"><ExternalLink size={16}/>Open Routal Planner</a></div><small className="mobileHint">In Routal, open or create today’s plan, choose Upload file, map the columns, then create and optimize the route. Routal will dispatch it to the driver app.</small></Card><Card title="Recommended priority order"><div className="stops">{stops.map((m:any,i:number)=><div><b>{i+1}</b><span><strong>{m[1]}</strong><small>{m[2]} · {m[6]}% stock</small></span><i>{m[3]!=='Active'?'Fault + refill':'Refill'}</i></div>)}</div><div className="routeNote"><CheckCircle2 size={18}/><span><b>Safe integration path</b><small>No Routal password or API key is stored in this browser. Automatic sync can be enabled later through a protected server connector.</small></span></div></Card></div></>}
function Table({heads,rows}:any){return <div className="table"><table><thead><tr>{heads.map((h:string)=><th>{h}</th>)}</tr></thead><tbody>{rows.map((r:any)=><tr>{r.map((v:any,i:number)=><td><b>{i===0?v:null}</b>{i?v:null}</td>)}</tr>)}</tbody></table></div>}
function Targets({d,set}:any){const[t,st]=useState(d.targets),[perms,setPerms]=useState<any>(readPermissions()),[security,setSecurity]=useState<any>(()=>JSON.parse(localStorage.getItem('aa-login-security')||'{}'));const toggle=(r:string,k:string)=>setPerms({...perms,[r]:{...perms[r],[k]:!perms[r][k]}}),changeSecurity=(r:string,k:string,v:any)=>setSecurity({...security,[r]:{enabled:false,passcode:'',...security[r],[k]:v}}),save=()=>{set({...d,targets:t});localStorage.setItem('aa-permissions',JSON.stringify(perms));localStorage.setItem('aa-login-security',JSON.stringify(security));location.reload()};return <><Card title="Login passcodes"><p>Master can protect any profile with a passcode or leave it open for direct access.</p><div className="passcodeGrid">{roles.map(([r,n,d])=><div><span><b>{n}</b><small>{d}</small></span><label className="switch"><input type="checkbox" checked={!!security[r]?.enabled} onChange={e=>changeSecurity(r,'enabled',e.target.checked)}/><i/></label><input type="password" inputMode="numeric" disabled={!security[r]?.enabled} value={security[r]?.passcode||''} onChange={e=>changeSecurity(r,'passcode',e.target.value)} placeholder="Set passcode"/></div>)}</div><small className="mobileHint">Local demo protection only. Production passcodes must be encrypted and checked by a secure server.</small></Card><EmployeePermissionsPanel/><Card title="Editable weekly targets"><p>Targets drive red and green indicators throughout the dashboard.</p><div className="form">{Object.entries(t).map(([k,v])=><label><span>{k.replace(/([A-Z])/g,' $1')}</span><input type="number" value={v as number} onChange={e=>st({...t,[k]:+e.target.value})}/></label>)}</div><button className="primary" onClick={save}><Save size={16}/>Save settings</button><button className="secondary" onClick={()=>{localStorage.removeItem('aa-data');localStorage.removeItem('aa-permissions');localStorage.removeItem('aa-login-security');location.reload()}}>Reset demo data</button></Card></>}
function Report({biz,d,set}:any){let k=biz==='vending'?'vending':'sales',done=d.submissions[k];return <Card title="Prior-week submission"><div className={`state ${done?'done':'missing'}`}>{done?<CheckCircle2/>:<AlertTriangle/>}<span><b>{done?'Weekly report submitted':'Weekly report outstanding'}</b><small>17–23 August 2026</small></span></div><div className="form"><label><span>Headline summary</span><textarea defaultValue={biz==='vending'?'Revenue increased 4.5%. Three refills and one urgent fault need attention.':'Eight vehicles sold. Rental utilisation reached 84%; two inspections await.'}/></label><label><span>Follow-up actions</span><textarea defaultValue="Record actions, owners and due dates here."/></label></div><button className="primary" onClick={()=>set({...d,submissions:{...d.submissions,[k]:true}})}><Save size={16}/>{done?'Update':'Submit'} weekly report</button></Card>}
type Reminder={id:number,text:string,when:string,assignee:Role,createdBy:Role,createdAt:string,triggered:boolean,dismissed:boolean};
function ReminderPanel(){const current=(sessionStorage.getItem('aa-role')||'owner') as Role,[items,setItems]=useState<Reminder[]>(()=>{try{return JSON.parse(localStorage.getItem('aa-reminders')||'[]')}catch{return[]}}),[text,setText]=useState(''),[when,setWhen]=useState(''),[assignee,setAssignee]=useState<Role>(current==='owner'?'keith':current),[alerts,setAlerts]=useState(false);const visible=current==='owner'?items:items.filter(x=>x.assignee===current),active=visible.find(x=>x.triggered&&!x.dismissed),person=(r:Role)=>roles.find(x=>x[0]===r)?.[1]||r,ring=()=>{try{const Ctx=window.AudioContext||(window as any).webkitAudioContext,ctx=new Ctx(),osc=ctx.createOscillator(),gain=ctx.createGain();osc.frequency.value=880;gain.gain.value=.16;osc.connect(gain);gain.connect(ctx.destination);osc.start();gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.7);osc.stop(ctx.currentTime+.7)}catch{}};useEffect(()=>localStorage.setItem('aa-reminders',JSON.stringify(items)),[items]);useEffect(()=>{const timer=setInterval(()=>setItems(old=>{const due=old.find(x=>x.assignee===current&&!x.triggered&&!x.dismissed&&new Date(x.when).getTime()<=Date.now());if(!due)return old;ring();if(Notification.permission==='granted')new Notification('A and A Holdings reminder',{body:due.text});return old.map(x=>x.id===due.id?{...x,triggered:true}:x)}),1000);return()=>clearInterval(timer)},[current]);const enable=async()=>{ring();if('Notification'in window){const p=await Notification.requestPermission();setAlerts(p==='granted')}else setAlerts(true)},add=(e:React.FormEvent)=>{e.preventDefault();if(!text.trim()||!when)return;setItems(x=>[...x,{id:Date.now(),text:text.trim(),when,assignee,createdBy:current,createdAt:new Date().toLocaleString('en-IE'),triggered:false,dismissed:false}]);setText('');setWhen('')};return <><Card title="Timed reminders"><div className="reminderTop"><form className="reminderForm" onSubmit={add}><input required value={text} onChange={e=>setText(e.target.value)} placeholder="What should we remind you about?"/><input required type="datetime-local" value={when} onChange={e=>setWhen(e.target.value)}/>{current==='owner'&&<select value={assignee} onChange={e=>setAssignee(e.target.value as Role)}>{roles.filter(x=>x[0]!=='owner').map(([r,n])=><option value={r}>{n}</option>)}</select>}<button className="primary"><Bell size={16}/>Set reminder</button></form><button className="enableAlerts" onClick={enable}>{alerts?'Alerts enabled':'Enable sound & alerts'}</button></div><div className="reminderList">{visible.filter(x=>!x.dismissed).length?visible.filter(x=>!x.dismissed).sort((a,b)=>a.when.localeCompare(b.when)).map(x=><div><Bell size={16}/><span><b>{x.text}</b><small>{person(x.assignee)} · {new Date(x.when).toLocaleString('en-IE')}</small><em>Created by {person(x.createdBy)} · {x.createdAt}</em></span></div>):<p>No active reminders.</p>}</div></Card>{active&&<div className="alarmOverlay"><div><Bell size={36}/><em>REMINDER</em><h2>{active.text}</h2><p>{new Date(active.when).toLocaleString('en-IE')}</p><small>Set by {person(active.createdBy)}</small><button onClick={()=>setItems(x=>x.map(r=>r.id===active.id?{...r,dismissed:true}:r))}>Dismiss reminder</button></div></div>}</>}
type LocationReminder={id:number,text:string,location:string,lat:number,lng:number,radius:number,assignee:Role,createdBy:Role,createdAt:string,triggered:boolean,dismissed:boolean};
function LocationReminderPanel(){const current=(sessionStorage.getItem('aa-role')||'owner') as Role,[items,setItems]=useState<LocationReminder[]>(()=>{try{return JSON.parse(localStorage.getItem('aa-location-reminders')||'[]')}catch{return[]}}),[text,setText]=useState(''),[location,setLocation]=useState(''),[radius,setRadius]=useState(200),[point,setPoint]=useState<{lat:number,lng:number}|null>(null),[assignee,setAssignee]=useState<Role>(current==='owner'?'driver':current),[monitoring,setMonitoring]=useState(false),[message,setMessage]=useState('');const person=(r:Role)=>roles.find(x=>x[0]===r)?.[1]||r,visible=current==='owner'?items:items.filter(x=>x.assignee===current),active=visible.find(x=>x.triggered&&!x.dismissed),distance=(a:number,b:number,c:number,d:number)=>{const R=6371000,p=Math.PI/180,x=(c-a)*p,y=(d-b)*p,q=Math.sin(x/2)**2+Math.cos(a*p)*Math.cos(c*p)*Math.sin(y/2)**2;return 2*R*Math.asin(Math.sqrt(q))},ring=()=>{try{const Ctx=window.AudioContext||(window as any).webkitAudioContext,ctx=new Ctx(),o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=760;g.gain.value=.18;o.connect(g);g.connect(ctx.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+1);o.stop(ctx.currentTime+1)}catch{}};useEffect(()=>localStorage.setItem('aa-location-reminders',JSON.stringify(items)),[items]);useEffect(()=>{if(!monitoring||!navigator.geolocation)return;const id=navigator.geolocation.watchPosition(pos=>setItems(old=>{const due=old.find(x=>x.assignee===current&&!x.triggered&&!x.dismissed&&distance(pos.coords.latitude,pos.coords.longitude,x.lat,x.lng)<=x.radius);if(!due)return old;ring();if('Notification'in window&&Notification.permission==='granted')new Notification('Location reminder',{body:due.text});return old.map(x=>x.id===due.id?{...x,triggered:true}:x)}),()=>setMessage('Location access was not available.'),{enableHighAccuracy:true,maximumAge:15000});return()=>navigator.geolocation.clearWatch(id)},[monitoring,current]);const capture=()=>navigator.geolocation.getCurrentPosition(p=>{setPoint({lat:p.coords.latitude,lng:p.coords.longitude});setMessage('Location captured successfully.')},()=>setMessage('Please allow location access to capture this site.'),{enableHighAccuracy:true}),add=(e:React.FormEvent)=>{e.preventDefault();if(!text.trim()||!location.trim()||!point)return;setItems(x=>[...x,{id:Date.now(),text:text.trim(),location:location.trim(),lat:point.lat,lng:point.lng,radius,assignee,createdBy:current,createdAt:new Date().toLocaleString('en-IE'),triggered:false,dismissed:false}]);setText('');setLocation('');setPoint(null);setMessage('Location reminder saved.')};return <div className="locationReminders"><div className="subHeading"><MapPin size={18}/><div><h3>Location reminders</h3><p>Trigger an alert when the assigned person approaches a saved site.</p></div><button onClick={()=>setMonitoring(x=>!x)}>{monitoring?'Location alerts on':'Enable location alerts'}</button></div><form onSubmit={add}><input required value={text} onChange={e=>setText(e.target.value)} placeholder="Reminder message"/><input required value={location} onChange={e=>setLocation(e.target.value)} placeholder="Machine or location name"/><label><span>Alert distance</span><select value={radius} onChange={e=>setRadius(+e.target.value)}><option value="100">100 metres</option><option value="200">200 metres</option><option value="500">500 metres</option></select></label>{current==='owner'&&<select value={assignee} onChange={e=>setAssignee(e.target.value as Role)}>{roles.filter(x=>x[0]!=='owner').map(([r,n])=><option value={r}>{n}</option>)}</select>}<button type="button" className={point?'captured':''} onClick={capture}><MapPin size={15}/>{point?'Location captured':'Capture current location'}</button><button className="primary" disabled={!point}>Save location reminder</button></form>{message&&<small className="locationMessage">{message}</small>}<div className="locationList">{visible.filter(x=>!x.dismissed).map(x=><div><MapPin size={16}/><span><b>{x.text}</b><small>{x.location} · within {x.radius}m · {person(x.assignee)}</small><em>Created by {person(x.createdBy)} · {x.createdAt}</em></span></div>)}</div>{active&&<div className="alarmOverlay"><div><MapPin size={36}/><em>LOCATION REMINDER</em><h2>{active.text}</h2><p>{active.location}</p><small>Set by {person(active.createdBy)}</small><button onClick={()=>setItems(x=>x.map(r=>r.id===active.id?{...r,dismissed:true}:r))}>Dismiss reminder</button></div></div>}</div>}
