function TaskBoard(){const current=(sessionStorage.getItem('aa-role')||'owner') as Role,[tasks,setTasks]=useState<WorkTask[]>(()=>{try{return JSON.parse(localStorage.getItem('aa-tasks')||'null')||seededTasks}catch{return seededTasks}}),[title,setTitle]=useState(''),[assignee,setAssignee]=useState<Role>(current==='owner'?'keith':current);useEffect(()=>localStorage.setItem('aa-tasks',JSON.stringify(tasks)),[tasks]);const visible=current==='owner'?tasks:tasks.filter(t=>t.assignee===current),name=(r:Role)=>roles.find(x=>x[0]===r)?.[1]||r,stamp=()=>new Intl.DateTimeFormat('en-IE',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date()),add=(e:React.FormEvent)=>{e.preventDefault();if(!title.trim())return;const now=stamp();setTasks(x=>[...x,{id:Date.now(),title:title.trim(),assignee,status:'todo',due:'No due date',createdBy:current,createdAt:now,lastBy:current,lastAt:now}]);setTitle('')},move=(task:WorkTask,status:TaskStatus)=>setTasks(x=>x.map(t=>t.id===task.id?{...t,status,lastBy:current,lastAt:stamp()}:t));const columns:[TaskStatus,string][]=[['todo','To do'],['progress','In progress'],['done','Completed']];return <><div className="taskIntro"><div><em>WORK MANAGEMENT</em><h2>{current==='owner'?'Team task overview':'My task board'}</h2><p>{current==='owner'?'Create, assign and monitor work across every profile.':'Move your work from To do, through In progress, to Completed.'}</p></div><b><ClipboardList size={18}/>{visible.length} tasks</b></div><form className="taskAdd" onSubmit={add}><input required value={title} onChange={e=>setTitle(e.target.value)} placeholder="Add task…"/>{current==='owner'&&<select value={assignee} onChange={e=>setAssignee(e.target.value as Role)}>{roles.filter(x=>x[0]!=='owner').map(([r,n])=><option value={r}>{n}</option>)}</select>}<button className="primary"><Plus size={16}/>Add task</button></form><div className="kanban">{columns.map(([status,label])=><section className={`kanbanCol ${status}`}><header><h3>{label}</h3><span>{visible.filter(t=>t.status===status).length}</span></header><div>{visible.filter(t=>t.status===status).map(t=><article className="taskCard"><small>{name(t.assignee)} · {t.due}</small><h4>{t.title}</h4><div className="signature"><b>Created by {name(t.createdBy)}</b><span>{t.createdAt}</span><b>Last changed by {name(t.lastBy)}</b><span>{t.lastAt}</span></div><div className="taskActions">{status!=='todo'&&<button onClick={()=>move(t,status==='done'?'progress':'todo')}>Move back</button>}{status!=='done'&&<button className="next" onClick={()=>move(t,status==='todo'?'progress':'done')}>{status==='todo'?'Start':'Finish'}<ArrowRight size={14}/></button>}</div></article>)}</div></section>)}</div><small className="mobileHint">Each card carries a visible signature showing who created it and who last changed its status. This demo saves on this device; the live system will keep a secure shared audit history.</small></>}
document.addEventListener('click',e=>{const link=(e.target as HTMLElement).closest<HTMLAnchorElement>('.mapsButton,.stops a');if(!link?.href)return;const ua=navigator.userAgent,params=new URL(link.href).searchParams,destination=params.get('destination');if(!destination)return;if(/Android/i.test(ua)){e.preventDefault();window.location.href=`google.navigation:q=${encodeURIComponent(destination)}&mode=d`}else if(/iPhone|iPad|iPod/i.test(ua)){e.preventDefault();window.location.href=`comgooglemaps://?saddr=&daddr=${encodeURIComponent(destination)}&directionsmode=driving`;setTimeout(()=>{window.location.href=link.href},1200)}});
